INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, "あたしだって\nやるときはやるよ！", 1, 24001, 0.0, "2030/12/17 14:59:59", 0.0, 1, 0, 10040, "リン", 24, "2020/04/30 12:00:00", 102601);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, "ふぅ…\nこれであたしの仕事は\n終わりだね", 1, 24002, 0.0, "2030/12/17 14:59:59", 0.0, 1, 1, 10040, "リン", 24, "2020/04/30 12:00:00", 102601);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, "終わった終わった\n一人でもなんとか\nなるもんだね", 1, 24003, 0.0, "2030/12/17 14:59:59", 0.0, 1, 2, 10040, "リン", 24, "2020/04/30 12:00:00", 102601);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, "やったね！\nこれでようやく\nサボれるよ…", 2, 24004, 0.0, "2030/12/17 14:59:59", 0.0, 2, 3, 10040, "リン", 24, "2020/04/30 12:00:00", 102601);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, "チーズが欲しいなら\nきちんと働いて\n買いに来なよ", 1, 24005, 0.0, "2030/12/17 14:59:59", 0.0, 1, 4, 10040, "リン", 24, "2020/04/30 12:00:00", 102601);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, "あたしを敵に回した\n恐ろしさ\n思い知ったか！", 2, 24006, 0.0, "2030/12/17 14:59:59", 0.0, 2, 5, 10040, "リン", 24, "2020/04/30 12:00:00", 102601);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, "あたしも意外と\nやるもんでしょ？", 2, 24007, 0.0, "2030/12/17 14:59:59", 0.0, 2, 6, 10040, "リン", 24, "2020/04/30 12:00:00", 102601);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, "疲れた…\nねずみの逃げ足\n速すぎるよ…", 4, 24008, 0.0, "2030/12/17 14:59:59", 0.0, 4, 7, 10040, "リン", 24, "2020/04/30 12:00:00", 102601);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, "このままじゃ\nまっひ～に\n叱られちゃうよ", 4, 24009, 0.0, "2030/12/17 14:59:59", 0.0, 4, 8, 10040, "リン", 24, "2020/04/30 12:00:00", 102601);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, "まじめに\nやったんだけどな…\n悔しいな～", 4, 24010, 0.0, "2030/12/17 14:59:59", 0.0, 4, 9, 10040, "リン", 24, "2020/04/30 12:00:00", 102601);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, "やられた…\nねずみって意外と\nてごわいね", 4, 24011, 0.0, "2030/12/17 14:59:59", 0.0, 4, 10, 10040, "リン", 24, "2020/04/30 12:00:00", 102601);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, "おのれ～\nあたしのチーズを\n盗みやがって～！", 4, 24012, 0.0, "2030/12/17 14:59:59", 0.0, 4, 11, 10040, "リン", 24, "2020/04/30 12:00:00", 102601);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (1.81, "疲れた…\nけど、次こそは\n守り抜くよ…", 1, 24013, 0.0, "2030/12/17 14:59:59", 0.0, 4, 12, 10040, "リン", 24, "2020/04/30 12:00:00", 102601);
